var n=`0922-egg-drop-soup`;var t=`world-0922`;var s=`CN`;var o=`east-asia`;var a=4;var g=24;var r={en:`Egg Drop Soup`,ua:`Яєчний суп`};var m={en:`Egg Drop Soup is a China dish made with cornstarch, chicken egg, green onion. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Яєчний суп, страва кухні країни Китай. Основні складники: кукурудзяний крохмаль, куряче яйце, зелена цибуля. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 12 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 12 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:12,i:[[`chicken-stock`,1120,`ml`],[`ground-ginger`,16,`g`],[`white-peppercorn`,2,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`cornstarch`,26,`g`],[`water`,65,`ml`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 4 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 4 хвилин до готовності й м’якості.`,t:[`poaching`],m:4,i:[[`chicken-egg`,4,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,40,`g`],[`toasted-sesame-oil`,15,`ml`]]}];var h={slug:n,id:t,country:`CN`,region:o,servings:4,minutes:24,title:r,text:m,steps:d};export{s as country,h as default,t as id,g as minutes,o as region,a as servings,n as slug,d as steps,m as text,r as title};